def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The three adjacent marks on the top edge define the color lanes.
    cols = [c for c, v in enumerate(grid[0]) if v]
    if len(cols) < 3:
        raise ValueError('expected three top-edge markers')
    # The first two lanes continue vertically; all matching off-key marks
    # extend horizontally back to their lane.
    for c in cols[:2]:
        color = grid[0][c]
        for r in range(h):
            out[r][c] = color
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and (r != 0 or c not in cols):
                anchors = [a for a in cols if grid[0][a] == color]
                if anchors:
                    a = anchors[0]
                    for x in range(min(a, c), max(a, c) + 1):
                        out[r][x] = color
    return out
